{"content":"package ini

import (
	"strings"
	"testing"
)

func TestAdHocDocBehaviour(t *testing.T) {
	doc := `
# comment
key = a=b=c
[ MiXed ]
x = "  keep  "
x = override
url = http://x/#frag
q = "a ; b"
p = 1  ; note
s = "v" ; trailing
`
	f, err := Parse(strings.NewReader(doc))
	if err != nil {
		t.Fatal(err)
	}
	check := func(sec, key, want string) {
		t.Helper()
		got, ok := f.Get(sec, key)
		if !ok || got != want {
			t.Errorf("%s.%s = %q,%v want %q", sec, key, got, ok, want)
		}
	}
	check("", "key", "a=b=c")
	check("mixed", "x", "override")
	check("mixed", "url", "http://x/#frag")
	check("mixed", "q", "a ; b")
	check("mixed", "p", "1")
	check("mixed", "s", "v")
}
","path":"ini/adhoc_test.go"}
